348	    /**
349	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
350	     * truth for how a telephone is compared and persisted, so inputs that differ only in
351	     * formatting (spaces, dashes, brackets) are treated as the same number.
352	     *
353	     * <p>The rules are:
354	     * <ul>
355	     *   <li>spaces, dashes and brackets are stripped;</li>
356	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
357	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
358	     *       is dropped from the national digits;</li>
359	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
360	     *   <li>for a recognized country code the national number (the digits after the country
361	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
362	     *       digits and {@code '+1'} requires 10.</li>
363	     * </ul>
364	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
365	     * values are returned unchanged.
366	     *
367	     * @param telephone the raw telephone, possibly {@code null}
368	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
369	     *     valid E.164 number
370	     */
371	    public static String normalizeTelephone(String telephone) {
372	        if (telephone == null) {
373	            return null;
374	        }
375	        String trimmed = telephone.trim();
376	        boolean hasCountryCode = trimmed.startsWith("+");
377	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
378	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
379	        if (hasCountryCode) {
380	            stripped = stripped.substring(1);
381	        }
382	        if (!stripped.matches("\\d+")) {
383	            return null;
384	        }
385	        String digits;
386	        if (hasCountryCode) {
387	            digits = stripped;
388	        } else {
389	            if (stripped.startsWith("0")) {
390	                stripped = stripped.substring(1);
391	            }
392	            digits = "61" + stripped;
393	        }
394	        if (digits.length() < 8 || digits.length() > 15) {
395	            return null;
396	        }
397	        if (!hasValidNationalNumberLength(digits)) {
398	            return null;
399	        }
400	        return "+" + digits;
401	    }
402	
403	    /**
404	     * Format a stored E.164 telephone for human display: the country code, a space, then the
405	     * national digits grouped left-to-right in blocks of three separated by spaces (e.g.
406	     * {@code "+61412345678"} becomes {@code "+61 412 345 678"}). The country code is identified
407	     * from the recognized {@link #NATIONAL_NUMBER_LENGTHS} table (longest prefix first); when no
408	     * recognized country code matches, the digits after the {@code '+'} are grouped in threes with
409	     * no separate country-code segment. This is a display-only transform; the raw E.164 value is
410	     * kept unchanged elsewhere.
411	     *
412	     * @param telephone the stored E.164 telephone, possibly {@code null}
413	     * @return the human-formatted telephone, or {@code null} when the input is {@code null}; an
414	     *     input that is not a well-formed E.164 number ({@code '+'} followed by digits) is returned
415	     *     unchanged
416	     */
417	    public static String telephoneDisplay(String telephone) {
418	        if (telephone == null) {
419	            return null;
420	        }
421	        if (!telephone.matches("\\+\\d+")) {
422	            return telephone;
423	        }
424	        String digits = telephone.substring(1);
425	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
426	            if (digits.startsWith(countryCode)) {
427	                return "+" + countryCode + " " + groupDigits(digits.substring(countryCode.length()));
428	            }
429	        }
430	        return "+" + groupDigits(digits);
431	    }
432	
433	    /**
434	     * Group a run of digits left-to-right into blocks of three separated by single spaces, with a
435	     * trailing block of one or two digits when the length is not a multiple of three (e.g.
436	     * {@code "412345678"} becomes {@code "412 345 678"}).
437	     *
438	     * @param digits the national digits
439	     * @return the space-grouped digits
440	     */
441	    private static String groupDigits(String digits) {
442	        StringBuilder grouped = new StringBuilder(digits.length() + digits.length() / 3);
443	        for (int i = 0; i < digits.length(); i++) {
444	            if (i > 0 && i % 3 == 0) {
445	                grouped.append(' ');
446	            }
447	            grouped.append(digits.charAt(i));
448	        }
449	        return grouped.toString();
450	    }
451	
452	    /**
453	     * Required national-number length (the count of digits after the country code) for each
454	     * recognized country code, longest country code first so the prefix match is unambiguous.
455	     */
456	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
457	    static {
458	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
459	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
460	    }
461	
462	    /**
463	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
464	     * length its country code requires. A country code with no registered length places no
465	     * additional constraint and is accepted.
466	     *
467	     * @param digits the E.164 digits without the leading {@code '+'}
468	     * @return {@code true} if the national-number length is valid for the country code
469	     */
470	    private static boolean hasValidNationalNumberLength(String digits) {
471	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
472	            String countryCode = entry.getKey();
473	            if (digits.startsWith(countryCode)) {
474	                return digits.length() - countryCode.length() == entry.getValue();
475	            }
476	        }
477	        return true;
478	    }
