480	    /**
481	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
482	     * upper-cased abbreviation.
483	     */
484	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
485	        "ST", "STREET",
486	        "RD", "ROAD",
487	        "AVE", "AVENUE");
488	
489	    /**
490	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
491	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
492	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
493	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
494	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
495	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
496	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
497	     * value. The transform is idempotent: a normalized address normalizes to itself.
498	     *
499	     * @param address the raw address, possibly {@code null}
500	     * @return the normalized form, or {@code null} if the input was {@code null}
501	     */
502	    public static String normalizeAddress(String address) {
503	        if (address == null) {
504	            return null;
505	        }
506	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
507	        if (collapsed.isEmpty()) {
508	            return collapsed;
509	        }
510	        String[] tokens = collapsed.split(" ");
511	        StringBuilder normalized = new StringBuilder(collapsed.length());
512	        for (int i = 0; i < tokens.length; i++) {
513	            if (i > 0) {
514	                normalized.append(' ');
515	            }
516	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
517	        }
518	        return normalized.toString();
519	    }
