521	    /**
522	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
523	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
524	     * result is that line, with a single space and {@code addressLine2} appended when the second line
525	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
526	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
527	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
528	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
529	     *
530	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
531	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
532	     * @param flatAddress the normalized flat address, possibly {@code null}
533	     * @return the composed address, or the flat value / {@code null} when no structured line is present
534	     */
535	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
536	        if (isPresent(addressLine1)) {
537	            if (isPresent(addressLine2)) {
538	                return addressLine1 + " " + addressLine2;
539	            }
540	            return addressLine1;
541	        }
542	        return flatAddress;
543	    }
