570	    /**
571	     * Normalize a household field (such as last name or address) to its canonical form for
572	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
573	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
574	     * that differ only in letter case or spacing are treated as the same value.
575	     *
576	     * @param value the raw field value, possibly {@code null}
577	     * @return the normalized form, or {@code null} if the input was {@code null}
578	     */
579	    public static String normalizeHousehold(String value) {
580	        if (value == null) {
581	            return null;
582	        }
583	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
584	    }
