586	    /**
587	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
588	     * last name (compared case-insensitively with collapsed whitespace, see
589	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
590	     * those two fields, so two owners who share a last name and postcode are assigned the same id
591	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
592	     * upper-cased hex characters of the SHA-256 digest of
593	     * {@code normalizedLastName + '|' + postcode}.
594	     *
595	     * @param lastName the owner's last name, possibly {@code null}
596	     * @param postcode the owner's postcode, possibly {@code null}
597	     * @return the household id, or {@code null} if either field is {@code null}
598	     */
599	    public static String householdId(String lastName, String postcode) {
600	        String normalizedLastName = normalizeHousehold(lastName);
601	        if (normalizedLastName == null || postcode == null) {
602	            return null;
603	        }
604	        String key = normalizedLastName + "|" + postcode;
605	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
606	    }
607	
608	    /**
609	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
610	     * shared primitive behind every hash-derived owner value (the household id and the member id's
611	     * HASH8 segment), so they all agree on algorithm and encoding.
612	     *
613	     * @param value the string to digest, never {@code null}
614	     * @return the 64-character lower-case hex digest
615	     */
616	    private static String sha256Hex(String value) {
617	        try {
618	            byte[] digest = MessageDigest.getInstance("SHA-256")
619	                .digest(value.getBytes(StandardCharsets.UTF_8));
620	            StringBuilder hex = new StringBuilder(digest.length * 2);
621	            for (byte b : digest) {
622	                hex.append(String.format("%02x", b));
623	            }
624	            return hex.toString();
625	        } catch (NoSuchAlgorithmException e) {
626	            // SHA-256 is a standard algorithm required to be present on every JVM.
627	            throw new IllegalStateException("SHA-256 not available", e);
628	        }
629	    }
