631	    /**
632	     * Build an owner's {@code memberId}, the single unified owner identity assigned once when the owner
633	     * is created. It is formatted {@code '<REGION><FY><HASH8><CHK>'} (no separators) where:
634	     * <ul>
635	     *   <li>{@code REGION} is the region code derived from the postcode (see
636	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
637	     *       in no known range,</li>
638	     *   <li>{@code FY} is the two-digit fiscal year of the registration date (the last two digits of
639	     *       the fiscal-year number, see {@link #fiscalYearNumber(LocalDate)}),</li>
640	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
641	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
642	     *       name (the same HASH8 used by the region-and-hash identity), and</li>
643	     *   <li>{@code CHK} is a single Luhn check digit (see {@link #luhn(String)}) over the digits of the
644	     *       {@code <REGION><FY><HASH8>} prefix.</li>
645	     * </ul>
646	     * The value is deterministic in the postcode, telephone, last name and registration date (e.g.
647	     * {@code 'NSW271A2B3C4D5'}); it carries no sequence number.
648	     *
649	     * @param postcode the owner's postcode, possibly {@code null}
650	     * @param telephone the owner's raw telephone, possibly {@code null}
651	     * @param lastName the owner's last name, possibly {@code null}
652	     * @param registrationDate the owner's registration date, possibly {@code null}
653	     * @return the member id, or {@code null} if the telephone, last name or registration date is
654	     *     {@code null}
655	     */
656	    public static String memberId(String postcode, String telephone, String lastName,
657	            LocalDate registrationDate) {
658	        if (telephone == null || lastName == null || registrationDate == null) {
659	            return null;
660	        }
661	        String region = regionForPostcode(postcode);
662	        if (region == null) {
663	            region = "UNKNOWN";
664	        }
665	        String fy = String.format("%02d", fiscalYearNumber(registrationDate) % 100);
666	        String normalizedTelephone = normalizeTelephone(telephone);
667	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
668	        String hash8 = sha256Hex(key).substring(0, 8).toUpperCase();
669	        String prefix = region + fy + hash8;
670	        return prefix + luhn(prefix);
671	    }
