673	    /**
674	     * Extract the {@code REGION} segment of a {@code memberId}: the leading run of letters before the
675	     * two-digit {@code FY} segment (see {@link #memberId(String, String, String, LocalDate)}). Because
676	     * {@code REGION} is always alphabetic and is immediately followed by digits, the region is the
677	     * {@code memberId}'s leading letters. A {@code null} member id, or one with no leading letter,
678	     * yields {@code 'UNKNOWN'}.
679	     *
680	     * @param memberId the owner's member id, possibly {@code null}
681	     * @return the region segment, or {@code 'UNKNOWN'} when none can be read
682	     */
683	    public static String regionOf(String memberId) {
684	        if (memberId == null) {
685	            return "UNKNOWN";
686	        }
687	        int end = regionEnd(memberId);
688	        return end == 0 ? "UNKNOWN" : memberId.substring(0, end);
689	    }
