691	    /**
692	     * Locate the end of a {@code memberId}'s {@code REGION} segment: the index just past its leading
693	     * run of letters, which is where the two-digit {@code FY} segment begins (see
694	     * {@link #memberId(String, String, String, LocalDate)}). This is the single place the memberId's
695	     * region/FY boundary is read, shared by {@link #regionOf(String)} and {@link #fiscalYear(String)}.
696	     *
697	     * @param memberId the owner's member id, never {@code null}
698	     * @return the index after the leading letters (0 when the member id starts with a non-letter)
699	     */
700	    private static int regionEnd(String memberId) {
701	        int i = 0;
702	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
703	            i++;
704	        }
705	        return i;
706	    }
