708	    /**
709	     * Compute an owner's {@code identityKey}, the single derived value through which all
710	     * duplicate detection is now expressed. It is the lower-case hex SHA-256 digest (see
711	     * {@link #sha256Hex(String)}) of the three identity components joined with {@code '|'}:
712	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where
713	     * <ul>
714	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
715	     *   <li>the lower-cased email (see {@link #normalizeEmail(String)}), or the empty string
716	     *       when no email is present, and</li>
717	     *   <li>the Soundex code of the last name (see {@link #soundex(String)}).</li>
718	     * </ul>
719	     * A {@code null} component is rendered as the empty string before hashing. Two owners are the
720	     * same identity only when their <em>whole</em> keys are equal; because the telephone is part of
721	     * the key, two members of the same household (same last name and postcode) with different
722	     * telephones have different keys and are not a hard duplicate.
723	     *
724	     * @param telephone the owner's raw telephone, possibly {@code null}
725	     * @param email the owner's email, possibly {@code null}
726	     * @param lastName the owner's last name, possibly {@code null}
727	     * @return the 64-character lower-case hex identity key, never {@code null}
728	     */
729	    public static String identityKey(String telephone, String email, String lastName) {
730	        String normalizedTelephone = normalizeTelephone(telephone);
731	        String normalizedEmail = normalizeEmail(email);
732	        String lastNameSoundex = soundex(lastName);
733	        String raw = (normalizedTelephone == null ? "" : normalizedTelephone)
734	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
735	            + "|" + (lastNameSoundex == null ? "" : lastNameSoundex);
736	        return sha256Hex(raw);
737	    }
