739	    /** Soundex digit for each consonant; vowels, {@code H}, {@code W} and {@code Y} map to '0'. */
740	    private static final Map<Character, Character> SOUNDEX_CODES = new HashMap<>();
741	    static {
742	        for (char c : "BFPV".toCharArray()) {
743	            SOUNDEX_CODES.put(c, '1');
744	        }
745	        for (char c : "CGJKQSXZ".toCharArray()) {
746	            SOUNDEX_CODES.put(c, '2');
747	        }
748	        for (char c : "DT".toCharArray()) {
749	            SOUNDEX_CODES.put(c, '3');
750	        }
751	        SOUNDEX_CODES.put('L', '4');
752	        for (char c : "MN".toCharArray()) {
753	            SOUNDEX_CODES.put(c, '5');
754	        }
755	        SOUNDEX_CODES.put('R', '6');
756	    }
757	
758	    /**
759	     * Compute the American Soundex code of a name: the upper-cased first letter followed by three
760	     * digits encoding the following consonants ({@code B,F,P,V}->1; {@code C,G,J,K,Q,S,X,Z}->2;
761	     * {@code D,T}->3; {@code L}->4; {@code M,N}->5; {@code R}->6), padded with zeros to length four.
762	     * Vowels ({@code A,E,I,O,U,Y}) separate codes; {@code H} and {@code W} are ignored so two
763	     * like-coded consonants on either side of them collapse to a single digit; adjacent letters with
764	     * the same code also collapse to one. Non-letters are stripped before coding. This is the single
765	     * source of truth for the surname component of the {@code identityKey} and the soft-match rule.
766	     *
767	     * @param name the raw name, possibly {@code null}
768	     * @return the four-character Soundex code, {@code null} if the input is {@code null}, or the empty
769	     *     string if the input contains no letters
770	     */
771	    public static String soundex(String name) {
772	        if (name == null) {
773	            return null;
774	        }
775	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
776	        if (letters.isEmpty()) {
777	            return "";
778	        }
779	        StringBuilder code = new StringBuilder();
780	        code.append(letters.charAt(0));
781	        char previous = SOUNDEX_CODES.getOrDefault(letters.charAt(0), '0');
782	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
783	            char c = letters.charAt(i);
784	            if (c == 'H' || c == 'W') {
785	                continue;
786	            }
787	            char digit = SOUNDEX_CODES.getOrDefault(c, '0');
788	            if (digit != '0' && digit != previous) {
789	                code.append(digit);
790	            }
791	            previous = digit;
792	        }
793	        while (code.length() < 4) {
794	            code.append('0');
795	        }
796	        return code.toString();
797	    }
