818	    /**
819	     * Compute an owner's {@code fiscalYear}, the fiscal year of a date formatted {@code 'FY<YY>'}
820	     * where {@code YY} is the last two digits of the fiscal-year number (see
821	     * {@link #fiscalYearNumber(LocalDate)}). The fiscal year starts on 1 July, so a date of
822	     * {@code 2026-08-01} yields {@code 'FY27'} and {@code 2026-03-01} yields {@code 'FY26'}.
823	     *
824	     * @param date the date to derive the fiscal year from, possibly {@code null}
825	     * @return the fiscal year, or {@code null} if {@code date} is {@code null}
826	     */
827	    public static String fiscalYear(LocalDate date) {
828	        if (date == null) {
829	            return null;
830	        }
831	        return String.format("FY%02d", fiscalYearNumber(date) % 100);
832	    }
