834	    /**
835	     * Read an owner's {@code fiscalYear} from its {@code memberId}, formatted {@code 'FY<YY>'} where
836	     * {@code YY} is the two-digit {@code FY} segment carried by the member id (the two digits that
837	     * immediately follow the {@code REGION} segment, see
838	     * {@link #memberId(String, String, String, LocalDate)}). Reading it back from the member id keeps
839	     * the response's fiscal-year value consistent with the one encoded in the unified identifier.
840	     *
841	     * @param memberId the owner's member id, possibly {@code null}
842	     * @return the fiscal year formatted {@code 'FY<YY>'}, or {@code null} when no two-digit segment can
843	     *     be read from the member id
844	     */
845	    public static String fiscalYear(String memberId) {
846	        if (memberId == null) {
847	            return null;
848	        }
849	        int start = regionEnd(memberId);
850	        if (start + 2 > memberId.length()) {
851	            return null;
852	        }
853	        String yy = memberId.substring(start, start + 2);
854	        return yy.matches("\\d{2}") ? "FY" + yy : null;
855	    }
