857	    /**
858	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
859	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
860	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
861	     * and gains 3 when the owner's tenure is more than one fiscal year (the tenure being the number
862	     * of elapsed fiscal years from {@code registrationDate} to today, see
863	     * {@link #fiscalYear(LocalDate)}). Because a newly created owner has zero tenure, the tenure
864	     * points accrue only once the owner has been a member for more than a full fiscal year.
865	     *
866	     * @param namesakeCount the owner's namesake count, possibly {@code null}
867	     * @param email the owner's email, possibly {@code null}
868	     * @param householdCount the number of members in the owner's household, possibly {@code null}
869	     * @param registrationDate the owner's registration date, possibly {@code null}
870	     * @return the membership points, a non-negative integer
871	     */
872	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
873	            LocalDate registrationDate) {
874	        int points = 0;
875	        if (email != null && !email.isEmpty()) {
876	            points += 2;
877	        }
878	        if (namesakeCount != null && namesakeCount == 0) {
879	            points += 1;
880	        }
881	        if (householdCount != null && householdCount >= 3) {
882	            points += 2;
883	        }
884	        if (registrationDate != null
885	            && fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1) {
886	            points += 3;
887	        }
888	        return points;
889	    }
