891	    /**
892	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
893	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
894	     *
895	     * @param membershipPoints the owner's membership points
896	     * @return the membership level, an integer from 1 to 4
897	     */
898	    public static int membershipLevel(int membershipPoints) {
899	        if (membershipPoints >= 6) {
900	            return 4;
901	        }
902	        if (membershipPoints >= 4) {
903	            return 3;
904	        }
905	        if (membershipPoints >= 2) {
906	            return 2;
907	        }
908	        return 1;
909	    }
