986	    /**
987	     * Derive this owner's {@code ownerSegment}, the marketing segment formatted
988	     * {@code '<TIER>_<AREA>'}. {@code TIER} is {@code 'PREMIUM'} when the owner's effective
989	     * membership level (see {@link #effectiveMembershipLevel()}) is 3 or more, otherwise
990	     * {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the owner's locality (see
991	     * {@link #locality(String)}) is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
992	     * otherwise {@code 'REGIONAL'}. The result is one of {@code 'PREMIUM_METRO'},
993	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}.
994	     *
995	     * @return the owner's {@code '<TIER>_<AREA>'} segment
996	     */
997	    public String ownerSegment() {
998	        String tier = effectiveMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
