1014	    /**
1015	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
1016	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
1017	     * inclusive low and high bound of the region's valid 4-digit postcodes
1018	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
1019	     * table (including {@code 'UNKNOWN'}) places no range constraint.
1020	     */
1021	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
1022	        "NSW", new int[] {2000, 2099},
1023	        "VIC", new int[] {3000, 3099},
1024	        "QLD", new int[] {4000, 4099});
