1026	    /**
1027	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
1028	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
1029	     * digits, or one that falls in no known range resolves to {@code null}.
1030	     *
1031	     * @param postcode the owner's postcode, possibly {@code null}
1032	     * @return the matching region, or {@code null} when no range contains the postcode
1033	     */
1034	    private static String regionForPostcode(String postcode) {
1035	        if (postcode == null || !postcode.matches("\\d{4}")) {
1036	            return null;
1037	        }
1038	        int value = Integer.parseInt(postcode);
1039	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
1040	            int[] range = entry.getValue();
1041	            if (value >= range[0] && value <= range[1]) {
1042	                return entry.getKey();
1043	            }
1044	        }
1045	        return null;
1046	    }
