1048	    /**
1049	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
1050	     * {@code null} or empty postcode is always valid. When present it must be exactly four
1051	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
1052	     * range the value must fall within that inclusive range. A city with no known region accepts
1053	     * any four-digit postcode. This is the single source of
1054	     * truth for postcode validity, shared by the DTO validation and any persistence path.
1055	     *
1056	     * @param postcode the owner's postcode, possibly {@code null}
1057	     * @param city the owner's city, possibly {@code null}
1058	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
1059	     */
1060	    public static boolean isPostcodeValidForCity(String postcode, String city) {
1061	        if (postcode == null || postcode.isEmpty()) {
1062	            return true;
1063	        }
1064	        if (!postcode.matches("\\d{4}")) {
1065	            return false;
1066	        }
1067	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
1068	        if (range == null) {
1069	            return true;
1070	        }
1071	        int value = Integer.parseInt(postcode);
1072	        return value >= range[0] && value <= range[1];
1073	    }
