1075	    /**
1076	     * Compute a single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
1077	     * characters are ignored. This is the standard Luhn check digit: each digit is weighted
1078	     * right-to-left, every second digit (starting with the rightmost) is doubled with digit sums above
1079	     * nine reduced by nine, and the check digit is the amount that brings the weighted sum up to the
1080	     * next multiple of ten. It is the shared primitive behind the {@code CHK} segment of the
1081	     * {@code memberId} (see {@link #memberId(String, String, String, LocalDate)}).
1082	     *
1083	     * @param value the string whose digits are summed, never {@code null}
1084	     * @return the Luhn check digit from 0 to 9
1085	     */
1086	    private static int luhn(String value) {
1087	        int sum = 0;
1088	        boolean dbl = true;
1089	        for (int i = value.length() - 1; i >= 0; i--) {
1090	            char c = value.charAt(i);
1091	            if (c < '0' || c > '9') {
1092	                continue;
1093	            }
1094	            int d = c - '0';
1095	            if (dbl) {
1096	                d *= 2;
1097	                if (d > 9) {
1098	                    d -= 9;
1099	                }
1100	            }
1101	            sum += d;
1102	            dbl = !dbl;
1103	        }
1104	        return (10 - (sum % 10)) % 10;
1105	    }
