1137	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
1138	     * date. The age in whole years is the number of completed years between {@code birthDate} and
1139	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
1140	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
1141	     * two fields and is only defined when both are present.
1142	     *
1143	     * @param birthDate the owner's date of birth, possibly {@code null}
1144	     * @param registrationDate the owner's registration date, possibly {@code null}
1145	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
1146	     *     is {@code null}
1147	     */
1148	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
1149	        if (birthDate == null || registrationDate == null) {
1150	            return null;
1151	        }
1152	        int age = Period.between(birthDate, registrationDate).getYears();
1153	        if (age < 18) {
1154	            return "MINOR";
1155	        }
1156	        if (age < 65) {
1157	            return "ADULT";
1158	        }
1159	        return "SENIOR";
1160	    }
