52	    /**
53	     * Dedicated audit logger. Successful owner creates emit a single line here carrying the new
54	     * owner's id, member id and registration date.
55	     */
56	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
57	
58	    /**
59	     * Dedicated notification logger. A successful owner create enqueues a welcome notification by
60	     * emitting a single line here carrying the new owner's id and member id.
61	     */
62	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
63	
64	    /**
65	     * Monotonically increasing sequence number stamped onto each {@link OwnerCreatedEvent}. Shared
66	     * across all creates so the emitted events form a strictly ordered, gap-free series.
67	     */
